rss.channel:
{{ site.Params.blog.title }}
{{ .Permalink }}

{{ with .Site.Language.Locale }}
{{.}}
{{ end }}
{{ .Date.Format "Mon, 02 Jan 2006 15:04:05 -0700" | safeHTML }}
{{- $list := first 25 (where site.RegularPages "Layout" "post") -}}
{{ range $list }}


  {{ .Title }}
  {{ .Permalink }}
  {{ .Date.Format "Mon, 02 Jan 2006 15:04:05 -0700" | safeHTML }}
  {{ with .Site.Params.author.email }}{{.}}{{ with $.Site.Params.author.name }} ({{.}}){{end}}{{end}}
  {{- if .Params.guid }}
  {{ .Params.guid }}
  {{- else -}}
  {{ .Permalink }}
  {{- end }}
  {{ (replace .Content "src=\"/blog/uploads/" (printf "src=\"%sblog/uploads/" site.BaseURL)) | html }}
  {{ .RawContent | html }}

{{ end }}
